+    plant(&world, &mut history, "B", cube(p(0.0, 0.0, 0.0), p(10.0, 10.0, 10.0)));
+    assert_eq!(state_of(&world, "A"), Some(MeshState::BoxOnly(BoxReason::SharedBox)));
