+    plant(&world, &mut history, "Jaw", cube(p(0.0, 0.0, 0.0), p(10.0, 5.0, 20.0)));
+    let cache = MeshStateCache::default();
+    let v1 = fixture_view::mesh_states_cached(&cache, &world, 1);
