+#[test]
+fn mark_and_unmark_are_undoable_commands() {
+    let world = new_world();
+    let mut history = History::default();
+    history.execute(&world, ImportModel::from_mesh("Vise", Mesh::from_facets(cube(p(0.0, 0.0, 0.0), p(5.0, 5.0, 5.0)))));
