+    // A name already carrying a plain model: update + mark, one unit.
+    history.execute(&world, ImportModel::from_mesh("Plate", mesh()));
+    let bigger = Mesh::from_facets(cube(p(0.0, 0.0, 0.0), p(9.0, 9.0, 2.0)));
